// ======================= ord-21…ord-23 · свои товары QA-AUTO-, продажа не регистрируется =======================

const EMPTY = 'עדיין לא נוספו פריטים — חפש מוצר למטה כדי להתחיל.';
const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const stamp = () => `${String(Date.now()).slice(-7)}${Math.floor(Math.random() * 10)}`;

async function openWalkIn(page: Page) {
  await page.goto('/orders/walk-in');
  await expect(page.getByRole('heading', { level: 1, name: 'מכירה מיידית' })).toBeVisible({ timeout: 30_000 });
  return page.getByRole('combobox', { name: 'חיפוש מוצר להוספה למכירה' });
}
const results = (page: Page) => page.getByRole('listbox', { name: 'תוצאות חיפוש מוצרים' });
/** Пункт списка, имя которого ровно `name` (дальше идут «נותרו N» / «אזל מהמלאי» и цена). */
const optionOf = (page: Page, name: string) =>
  results(page).getByRole('option', { name: new RegExp(`^${esc(name)}\\s+(נותרו|אזל)`) });
const optionName = (text: string) => text.split(/\s*(?:נותרו|אזל מהמלאי)/)[0].replace(/\s+/g, ' ').trim();
const qtyOf = (page: Page, name: string) => page.getByRole('textbox', { name: `כמות — ${name}`, exact: true });
const allRows = (page: Page) => page.getByRole('textbox', { name: /^כמות — / });
const addedMsg = (page: Page) => page.getByRole('status').filter({ hasText: 'נוסף:' });

/** Текст выделенного пункта: aria-activedescendant поля, иначе aria-selected / data-highlighted / data-active у option. */
async function highlightedText(search: Locator, list: Locator): Promise<string> {
  const active = await search.getAttribute('aria-activedescendant');
  if (active) {
    const byId = list.locator(`[id="${active}"]`);
    if (await byId.count()) return byId.innerText();
  }
  const marked = list.locator('[role="option"][aria-selected="true"], [role="option"][data-highlighted], [role="option"][data-active="true"]');
  return (await marked.count()) ? marked.first().innerText() : '';
}

/** Ввести запрос, дождаться пункта `name`, Enter, дождаться строки `name`. */
async function addByEnter(page: Page, search: Locator, name: string) {
  await search.fill(name);
  await expect(optionOf(page, name)).toBeVisible({ timeout: 20_000 });
  await search.press('Enter');
  await expect(qtyOf(page, name)).toBeVisible({ timeout: 15_000 });
}

async function withAdmin<T>(browser: Browser, fn: (page: Page) => Promise<T>) {
  const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
  try { return await fn(await ctx.newPage()); } finally { await ctx.close(); }
}

// ---------- #5711c3 · ord-21 ----------
test.describe('orders — מכירה מיידית: Enter בחיפוש מוסיף התאמה מדויקת (#5711c3)', () => {
  test.describe.configure({ mode: 'default' });
  const ts = stamp();
  const P = `QA-AUTO-5711-${ts}`;
  const EXACT = `${P} צהוב`;           // точное, остаток 3
  const LONGER = `${P} ארוך צהוב`;     // по алфавиту раньше, остаток 3
  const OOS = `${P} ירוק`;             // точное, остаток 0
  const OTHER = `טבק ${P} ירוק`;       // содержит OOS, остаток 3
  const SKU_LONGER = `Q5711-${ts}-A2`;
  const created: string[] = [];

  test.beforeAll(async ({ browser }) => {
    test.setTimeout(300_000);
    await withAdmin(browser, async (page) => {
      for (const [name, sku] of [[EXACT, `Q5711-${ts}-A1`], [LONGER, SKU_LONGER], [OTHER, `Q5711-${ts}-B2`]]) {
        created.push(name);
        await createStockedProduct(page, name, sku, 1, 3);
      }
      created.push(OOS);
      await createProduct(page, OOS, `Q5711-${ts}-B1`, 1);
    });
  });
  test.afterAll(async ({ browser }) => {
    test.setTimeout(180_000);
    await cleanup(browser, [], created);
  });

  test('שם מלא + Enter — נוסף המוצר עם השם הזהה, הוא ראשון ומסומן ברשימה #5711c3 @desktop @orders @data', async ({ page }) => {
    const search = await openWalkIn(page);
    await search.fill(EXACT);
    await expect(optionOf(page, EXACT)).toBeVisible({ timeout: 20_000 });
    await expect(optionOf(page, LONGER)).toBeVisible();
    await expect(results(page).getByRole('option').first(), 'точное совпадение — первым').toHaveAccessibleName(new RegExp(`^${esc(EXACT)}\\s+נותרו`));
    await expect.poll(async () => optionName(await highlightedText(search, results(page))), { message: 'точное совпадение выделено' }).toBe(EXACT);
    await search.press('Enter');
    await expect(qtyOf(page, EXACT)).toHaveValue('1');
    await expect(allRows(page)).toHaveCount(1);
    await expect(qtyOf(page, LONGER)).toHaveCount(0);
    await expect(addedMsg(page)).toContainText(`נוסף: ${EXACT}`);
  });

  test('מק"ט מדויק + Enter — נוסף המוצר עם המק"ט #5711c3 @desktop @orders @data', async ({ page }) => {
    const search = await openWalkIn(page);
    await search.fill(SKU_LONGER);
    await expect(optionOf(page, LONGER)).toBeVisible({ timeout: 20_000 });
    await search.press('Enter');
    await expect(qtyOf(page, LONGER)).toHaveValue('1');
    await expect(allRows(page)).toHaveCount(1);
  });

  test('שם חלקי + Enter — נוסף הפריט המסומן (הראשון) ברשימה #5711c3 @desktop @orders @data', async ({ page }) => {
    const search = await openWalkIn(page);
    await search.fill(P);
    await expect(results(page).getByRole('option', { name: new RegExp(esc(P)) })).not.toHaveCount(0, { timeout: 20_000 });
    await expect(optionOf(page, LONGER)).toBeVisible();
    const first = optionName(await results(page).getByRole('option').first().innerText());
    await expect.poll(async () => optionName(await highlightedText(search, results(page))), { message: 'выделен первый пункт' }).toBe(first);
    await search.press('Enter');
    await expect(qtyOf(page, first)).toBeVisible({ timeout: 15_000 });
    await expect(allRows(page)).toHaveCount(1);
  });

  test('אותיות קטנות ורווחים בקצוות + Enter — עדיין ההתאמה המדויקת #5711c3 @desktop @orders @data', async ({ page }) => {
    const search = await openWalkIn(page);
    await search.fill(`  ${EXACT.toLowerCase()}  `);
    await expect(optionOf(page, EXACT)).toBeVisible({ timeout: 20_000 });
    await search.press('Enter');
    await expect(qtyOf(page, EXACT)).toHaveValue('1');
    await expect(allRows(page)).toHaveCount(1);
  });

  test.skip('התאמה מדויקת שאזלה מהמלאי + Enter — «אזל מהמלאי», שום מוצר לא נוסף #5711c3 @desktop @orders @data', { annotation: { type: 'skip', description: 'временно отключено 26.10 по просьбе клиента (#e7e338, лимит остатка снят); вернуть вместе с #e02e48 — knowledge/stock-logic-snapshot-2026-10-26.md §5' } }, async ({ page }) => {
    const search = await openWalkIn(page);
    await search.fill(OOS);
    await expect(optionOf(page, OOS)).toContainText('אזל מהמלאי', { timeout: 20_000 });
    await expect(optionOf(page, OTHER)).toBeVisible();
    await search.press('Enter');
    await expect(page.getByText(`${OOS} — אזל מהמלאי.`, { exact: true })).toBeVisible();
    await expect(allRows(page)).toHaveCount(0);
    await expect(qtyOf(page, OTHER)).toHaveCount(0);
    await expect(page.getByText(EMPTY)).toBeVisible();
    await expect(addedMsg(page)).toHaveCount(0);
  });
});

// ---------- #ccd3fa · ord-22 ----------
test.describe('orders — מכירה מיידית: באנר «הכמות … אינה תקינה» נעלם אחרי תיקון (#ccd3fa)', () => {
  test.describe.configure({ mode: 'default' });
  const ts = stamp();
  const Q = `QA-AUTO-ccd3-${ts}`;
  const banner = (page: Page) => page.getByText(`הכמות של ${Q} אינה תקינה. עדכן אותה ונסה שוב.`, { exact: true });

  test.beforeAll(async ({ browser }) => {
    test.setTimeout(120_000);
    await withAdmin(browser, (page) => createStockedProduct(page, Q, `Qccd3-${ts}`, 1, 3));
  });
  test.afterAll(async ({ browser }) => {
    test.setTimeout(120_000);
    await cleanup(browser, [], [Q]);
  });

  /** Кол-во 1.5 → «רישום המכירה» → баннер; продажа не начинается. */
  async function invalidQty(page: Page) {
    const search = await openWalkIn(page);
    await addByEnter(page, search, Q);
    await qtyOf(page, Q).fill('1.5');
    await page.getByRole('button', { name: 'רישום המכירה' }).click();
    await expect(banner(page)).toBeVisible();
    await expect(page.getByRole('dialog')).toHaveCount(0);
  }

  test('תיקון הכמות ל-2 בהקלדה — הבאנר נעלם מיד #ccd3fa @desktop @orders @data', async ({ page }) => {
    await invalidQty(page);
    await qtyOf(page, Q).fill('2');
    await expect(banner(page)).toHaveCount(0);
    await expect(qtyOf(page, Q)).toHaveValue('2');
    await page.getByRole('button', { name: 'חזרה להזמנות' }).click(); // продажу не регистрируем
  });

  test('תיקון הכמות ב-«+» — הבאנר נעלם מיד #ccd3fa @desktop @orders @data', async ({ page }) => {
    await invalidQty(page);
    await page.getByRole('button', { name: `הוספת יחידה — ${Q}` }).click();
    await expect(banner(page)).toHaveCount(0);
    await expect(qtyOf(page, Q)).toHaveValue('2');
    await page.getByRole('button', { name: 'חזרה להזמנות' }).click();
  });

  test('מחיקת השורה — הבאנר נעלם מיד #ccd3fa @desktop @orders @data', async ({ page }) => {
    await invalidQty(page);
    await page.getByRole('button', { name: `הסרת ${Q}` }).click();
    await expect(banner(page)).toHaveCount(0);
    await expect(page.getByText(EMPTY)).toBeVisible();
  });
});

// ---------- #0a50ac · ord-23 ----------
test.describe('orders — מכירה מיידית: ההודעה «נוסף: …» נעלמת אחרי מחיקת המוצר (#0a50ac)', () => {
  test.describe.configure({ mode: 'default' });
  const ts = stamp();
  const X = `QA-AUTO-0a50-${ts} X`;
  const Y = `QA-AUTO-0a50-${ts} Y`;

  test.beforeAll(async ({ browser }) => {
    test.setTimeout(180_000);
    await withAdmin(browser, async (page) => {
      await createStockedProduct(page, X, `Q0a50-${ts}-X`, 1, 3);
      await createStockedProduct(page, Y, `Q0a50-${ts}-Y`, 1, 3);
    });
  });
  test.afterAll(async ({ browser }) => {
    test.setTimeout(120_000);
    await cleanup(browser, [], [X, Y]);
  });

  async function addThenDeleteOnly(page: Page) {
    const search = await openWalkIn(page);
    await addByEnter(page, search, X);
    await expect(addedMsg(page)).toContainText(`נוסף: ${X}`);
    await page.getByRole('button', { name: `הסרת ${X}` }).click();
    await expect(page.getByText(EMPTY)).toBeVisible();
    await expect(addedMsg(page)).toHaveCount(0);
  }

  test('מחיקת השורה היחידה — אין «נוסף: …» ליד המצב הריק #0a50ac @desktop @orders @data', async ({ page }) => {
    await addThenDeleteOnly(page);
  });

  test('X ו-Y, מחיקת Y — ההודעה «נוסף: Y» נעלמת, X נשאר #0a50ac @desktop @orders @data', async ({ page }) => {
    const search = await openWalkIn(page);
    await addByEnter(page, search, X);
    await addByEnter(page, search, Y);
    await expect(addedMsg(page)).toContainText(`נוסף: ${Y}`);
    await page.getByRole('button', { name: `הסרת ${Y}` }).click();
    await expect(qtyOf(page, Y)).toHaveCount(0);
    await expect(addedMsg(page)).toHaveCount(0);
    await expect(qtyOf(page, X)).toHaveValue('1');
    await page.getByRole('button', { name: 'חזרה להזמנות' }).click(); // продажу не регистрируем
  });

  test('בטלפון 390: מחיקת השורה היחידה — אין «נוסף: …» #0a50ac @iphone @orders @data', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await addThenDeleteOnly(page);
  });
});
